* THIS CODE CREATES THE SAS PC DATA SET A4F05.
* VERSION 1.4 OF THE CARDIA SAS FILES
* SEPTEMBER 1989
*
* CALCULATED VARIABLES INCLUDED:
*
*
*
*
*
A05FAST
'12 HR FAST BEFORE BLOOD DRAWN'
A05FSTMN 'NUMBER OF MINUTES FASTING'
A05TMEAT 'TIME LAST ATE (SAS TIME VALUE)'
A05DTEAT 'DATE LAST ATE (SAS DATE VALUE)'
A05DTBLD 'DATE BLOOD DRAWN (SAS DATE VALUE)'
A05TMBLD 'TIME BLOOD DRAWN (SAS TIME VALUE)'
A05TMSPN 'TIME SPECIMEN WAS SPUN (SAS TIME VALUE)'
A05TMFRZ 'TIME SPECIMEN WAS FROZEN (SAS TIME VALUE)'
*****************************************************************************;
OPTIONS PS=59;

LIBNAME REF 'D:\UMASAS';
LIBNAME OUT 'D:\UMASAS';

DATA TEMP;
INFILE 'E:\X1-SEQ\FORM05.SEQ' LRECL=157;
MISSING M;

INPUT CENTER 1 ID 1-12
@61 A05PHLID 3. A05EATTM $CHAR4. A05EATDT $CHAR6.
@74 A05AIDS 1. A05HEMO 1. A05BLDDT $CHAR6. A05BLDTM $CHAR4. @;
*****************************************************************************
* TO INSERT SAS DATE & TIME VALUES IN POSITION OF CHAR VARIABLES
*****************************************************************************;

IF A05BLDDT='000000' THEN DO;
A05DTBLD=.;
END;
ELSE DO;
MO = INPUT( SUBSTR( A05BLDDT, 1, 2 ), 2.0 );
DY = INPUT( SUBSTR( A05BLDDT, 3, 2 ), 2.0 );
YR = INPUT( SUBSTR( A05BLDDT, 5, 2 ), 2.0 );
A05DTBLD = MDY( MO, DY, YR );
END;
DROP A05BLDDT YR MO DY;

IF A05EATDT='000000' THEN DO;
A05DTEAT=.;
END;
ELSE DO;
MO = INPUT( SUBSTR( A05EATDT, 1, 2 ), 2.0 );
DY = INPUT( SUBSTR( A05EATDT, 3, 2 ), 2.0 );
YR = INPUT( SUBSTR( A05EATDT, 5, 2 ), 2.0 );
A05DTEAT = MDY ( MO, DY, YR );
END;
DROP A05EATDT YR MO DY;

HH1 = INPUT( SUBSTR( A05EATTM, 1, 2 ), 2.0 );
