```

A05TMEAT = HMS(HH1, MM1, 0 );
DROP A05EATTM ;

HH2 = INPUT(SUBSTR( A05BLDTM, 1, 2 ), 2.0 );
MM2 = INPUT(SUBSTR( A05BLDTM, 3, 2 ), 2.0 );
A05TMBLD = HMS(HH2, MM2, 0 );
DROP A05BLDTM;
*****************************************************************
* NOW TO DETERMINE WHETHER INDIVIDUALS WERE FASTING OR NOT.
* THIS SECTION CREATES TWO VARIABLES A05FAST (FASTING: YES, NO) AND
* A05FSTMN (THE NUMBER OF MINUTES BETWEEN LAST ATE AND BLOOD DRAW.
*****************************************************************;

DTDIF=A05DTBLD-A05DTEAT;
IF DTDIF=0 THEN DO;
 IF (MM2-MM1) GE 0 THEN DO;
  HRS=HH2-HH1;
  MIN=MM2-MM1;
 END;
 IF ((MM2-MM1) LT 0) AND ((MM2-MM1) NE .) THEN DO;
  HRS=HH2-HH1-1;
  MIN=(60-MM1)+MM2;
 END;
END;

IF DTDIF>=1 THEN DO;
 HRS=(24-HH1)+HH2-1;
 MIN=(60-MM1)+MM2;

 IF MIN>=60 THEN DO;
  HRS=HRS+1;
  MIN=MOD(MIN,60);
 END;
END;

IF DTDIF>1 THEN DO;
 HRS=HRS+((DTDIF-1)*24);
END;

A05FSTMN=(HRS*60)+MIN;
*****************************************************************
* THE FOLLOWING CODE SETS A05FSTMN TO MISSING WHEN IT IS LESS THAN 0. *
* SIMILARLY IF A05FSTMN IS MISSING THE CODE SETS A05FST TO MISSING. *
*****************************************************************;

IF A05FSTMN LT 0 THEN A05FSTMN=.;
IF 720<=A05FSTMN<=2940 THEN A05FAST='YES';
IF 0<A05FSTMN<720 THEN A05FAST='NO ';
IF A05FSTMN=. THEN A05FAST=' ';

DROP HH1 HH2 MM1 MM2 DTDIF HRS MIN;
