%include 'c:\qdrive\sas\pud\polyx.sas';
data temp;
merge orig.c1f9prg1 (in=inorig)
new.pid;
by short_id;
if inorig;
* Create temporary variables for transformations;
array pvar c09npreg c09nlbir;
array new temp1 temp2;
do a=1 to dim(pvar);
if pvar[a]>0 then new[a]=pvar[a];
end;
/*
title2 'ORIGINAL VARIABLE';
