%confrun(temp2,'NLBIR');
proc sort data=temp; by pid;
run;
data new.caf9prg1;
set temp;
if gr=' ' then delete;
* Reset values due to transformations;
array pvar c09npreg c09nlbir;
array new temp1 temp2;
do b=1 to dim(pvar);
if pvar[b]>0 then pvar[b]=new[b];
end;
* Delete CARDIA ID variables;
drop id center shortid short_id gr a b temp1 temp2;
proc contents;
title 'CARDIA PUBLIC USE DATA - VERSION 1.0';
run;
