* DAREF.SAS;
* PROGRAM FOR CREATING PUBLIC USE DATASETS DAREF.SD2;
* P.SEKAR 10/99;
OPTIONS PS=59 LS=75 MACROGEN;
LIBNAME ORIG 'Q:\SAS\V612\Y7';
LIBNAME NEW 'Q:\SAS\PUB';
%INCLUDE 'Q:\SAS\PUB\DICHX.SAS';
%INCLUDE 'Q:\SAS\PUB\CONTX.SAS';
%INCLUDE 'Q:\SAS\PUB\BDATEX.SAS';
%INCLUDE 'Q:\SAS\PUB\POLYX.SAS';
DATA TEMP;
MERGE ORIG.D1REFA
NEW.PID;
BY ID;
TITLE2 'ORIGINAL VARIABLE';
%POLYX(A03ED);
%POLYX(D03ED);
%POLYX(X4STATUS);
DATA TEMP;
SET TEMP;
*EDUCATION LESS THAN OR EQUAL 10YRS=10 AND GREATER THAN OR EQUAL
16YRS=16;
IF .Z<A03ED<=10 THEN A03ED=10;
ELSE IF A03ED>=16 THEN A03ED=16;
*YEAR 7 EDUCATION, <=11=11, >18=18;
IF D03ED>20 THEN D03ED=99;
ELSE IF .Z<D03ED<=11 THEN D03ED=11;
ELSE IF D03ED>=18 THEN D03ED=18;
*EXAMINED AT OTHER CENTERS, ABBREVIATED EXAM='E',
NOT EXAMINED FOR ANY OTHER REASON='N'
CARDIA PUBLIC USE DATA DOCUMENTATION 1.0 Page 4
DAREF 10/99

AND DIED REMAINS THE SAME;
IF X4STATUS IN ('H', '1', '2', '3', '4') THEN X4STATUS='E';
ELSE IF X4STATUS IN ('L','R','P','N','S','U') THEN X4STATUS='N';
ELSE IF X4STATUS='Z' THEN X4STATUS='D';
RUN;
TITLE2 'TRANSFORMED VARIABLE';
%POLYX(A03ED);
%POLYX(D03ED);
%POLYX(X4STATUS);
TITLE2;
