%DATEX(X4DATE);
%DATEX(B02DATE);
%DATEX(C02DATE);
%DATEX(D02DATE);
PROC SORT DATA=TEMP; BY PID;
RUN;
DATA NEW.DAREF;
SET TEMP;
* SPECIAL CODING REQUIRED;
IF .<EXAMAGE <18 THEN DO;
EXAMAGE=18;
END;
ELSE IF EXAMAGE>30 THEN DO;
